using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly MetricsResponse _metrics;
    private readonly string[] _categoryLabels;

    public TicketClassifierService()
    {
        _mlContext = new MLContext(seed: 0);

        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        IDataView dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);

        // Extract category labels from the trained model's key-value mapping
        var transformedData = _model.Transform(dataView);
        var labelColumn = transformedData.Schema["Label"];
        var keyValues = new VBuffer<ReadOnlyMemory<char>>();
        labelColumn.GetKeyValues(ref keyValues);
        _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();

        // Evaluate with cross-validation for small datasets
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");

        var bestRun = cvResults.OrderByDescending(r => r.Metrics.MacroAccuracy).First();
        var metrics = bestRun.Metrics;

        _metrics = new MetricsResponse
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
            PerCategory = metrics.PerClassLogLoss
                .Select((logLoss, i) => new CategoryMetric
                {
                    Category = i < _categoryLabels.Length ? _categoryLabels[i] : $"Class_{i}",
                    Precision = i < metrics.ConfusionMatrix.PerClassPrecision.Count
                        ? metrics.ConfusionMatrix.PerClassPrecision[i] : 0,
                    Recall = i < metrics.ConfusionMatrix.PerClassRecall.Count
                        ? metrics.ConfusionMatrix.PerClassRecall[i] : 0,
                    F1Score = ComputeF1(
                        i < metrics.ConfusionMatrix.PerClassPrecision.Count
                            ? metrics.ConfusionMatrix.PerClassPrecision[i] : 0,
                        i < metrics.ConfusionMatrix.PerClassRecall.Count
                            ? metrics.ConfusionMatrix.PerClassRecall[i] : 0)
                })
                .ToList()
        };

        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _categoryLabels.Length; i++)
        {
            confidence[_categoryLabels[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            Category = prediction.Category,
            Confidence = confidence
        };
    }

    public MetricsResponse GetMetrics() => _metrics;

    private static double ComputeF1(double precision, double recall) =>
        precision + recall == 0 ? 0 : 2 * precision * recall / (precision + recall);
}

